style.css:
@-moz-document domain("roblox.com") {
/* Hintergrundbild */
body {
background-image: url("https://cdn.discordapp.com/attachments/1386970416102510672/1401590997514850356/dark_flower_tifa_cutesyhales.jpg?ex=689c0996&is=689ab816&hm=d654f52bcb3cee955eca67d2c76ffe7e473996e3038cdd9bde549433fde0bdfd&");
background-size: cover;
background-attachment: fixed;
background-position: center;
background-repeat: no-repeat;
}

/* Transparenter weißer Hintergrund für Inhalte */
.content,
.container,
.main-container {
background: rgba(255, 255, 255, 0.8) !important;
border-radius: 12px;
padding: 10px;
}

/* Überschriften anpassen */
h1, h2, h3 {
color: #ff69b4 !important; /* Pink */
font-family: "Comic Sans MS", cursive, sans-serif;
}

/* Buttons anpassen */
button, .btn-primary {
background-color: #ff69b4 !important;
border: none !important;
color: white !important;
font-weight: bold;
}

button:hover, .btn-primary:hover {
background-color: #ff1493 !important;
}
}
